def clock(cx, cy, c, deg):
    a = math.radians(deg)
    return [O(cx, cy, 24, 24, c, 16), O(cx, cy, 20, 20, CR, 16), line(cx, cy, cx, cy - 14, 3, IN), line(cx, cy, round(cx + 12 * math.cos(a)), round(cy + 12 * math.sin(a)), 3, IN)]


def flame(cx, b, s, c=OR):
    return [P([(cx - 20 * s, b), (cx - 10 * s, b - 40 * s), (cx, b - 24 * s), (cx + 8 * s, b - 60 * s), (cx + 20 * s, b)], c), P([(cx - 8 * s, b), (cx, b - 24 * s), (cx + 8 * s, b)], HL)]


